import os,sys,zlib,base64
if not os.path.exists('www/index.html'):
    os.chdir('/workspaces/PORTAL_CONDUCTOR/portal')
PARTES=[
('v3.7',''),
('v3.9',''),
('v3.10',''),
('v3.11','')
]
for nombre,blob in PARTES:
    print('=== '+nombre)
    code=zlib.decompress(base64.b64decode(blob)).decode('utf-8')
    try:
        exec(compile(code,nombre+'.py','exec'),{'__name__':'__main__'})
    except SystemExit as e:
        if e.code not in (None,0):
            print(e.code); sys.exit(1)
